struct SessionFwd {
    tgt: Arc<Session>,
    live: Arc<AtomicBool>,
}

impl Session for SessionFwd {
    fn write(&self, b: &[u8]) -> Result<(), Revoked> {
        if !self.live.load(Ordering::Acquire) { return Err(Revoked); }
        self.tgt.write(b)
    }
}
